13	
14	fn registry() -> CardRegistry {
15	    CardRegistry::with_all_cards()
16	}
17	
18	#[test]
19	
20	fn selfless_cathar_pump_all_creatures() {
21	    let reg = registry();
22	    let mut state = game_at_step(Step::PrecombatMain, P0);
23	
24	    let cathar = named_creature(&mut state, &reg, "Selfless Cathar", P0);
25	    let bear = ready_creature(&mut state, P0, 2, 2);
26	
27	    // Add mana for the ability: {1}{W}
28	    state.get_player_mut(P0).mana_pool.add(ManaType::White, 1);
29	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 1);
30	
31	    let new_state = mtg_engine::engine::submit_action(
32	        &state,
33	        &Action::ActivateAbility {
34	            object_id: cathar,
35	            ability_index: 0,
36	            targets: vec![],
37	        },
38	        &reg,
39	    );
40	
41	    // Cathar should be in graveyard (sacrificed).
42	    assert_eq!(
43	        new_state.get_object(cathar).unwrap().zone,
44	        Zone::Graveyard,
45	        "Selfless Cathar should be sacrificed"
46	    );
47	
48	    // Bear should have +1/+1 from the effect.
49	    assert_eq!(new_state.effective_power(bear, &reg).unwrap(), 3);
50	    assert_eq!(new_state.effective_toughness(bear, &reg).unwrap(), 3);
51	}
52	#[test]
53	
54	fn silverchase_fox_exiles_enchantment() {
55	    let reg = registry();
56	    let mut state = game_at_step(Step::PrecombatMain, P0);
57	
58	    let fox = named_creature(&mut state, &reg, "Silverchase Fox", P0);
59	
60	    // Create an enchantment for P1 (use Pacifism as a representative enchantment).
61	    let enchantment = named_creature(&mut state, &reg, "Glorious Anthem", P1);
62	
63	    // Add mana for the ability: {1}{W}
64	    state.get_player_mut(P0).mana_pool.add(ManaType::White, 1);
65	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 1);
66	
67	    let new_state = mtg_engine::engine::submit_action(
68	        &state,
69	        &Action::ActivateAbility {
70	            object_id: fox,
71	            ability_index: 0,
72	            targets: vec![Target::Object(enchantment)],
73	        },
74	        &reg,
75	    );
76	
77	    // Fox should be in graveyard (sacrificed).
78	    assert_eq!(
79	        new_state.get_object(fox).unwrap().zone,
80	        Zone::Graveyard,
81	        "Silverchase Fox should be sacrificed"
82	    );
83	
84	    // Enchantment should be in exile.
85	    assert_eq!(
86	        new_state.get_object(enchantment).unwrap().zone,
87	        Zone::Exile,
88	        "Target enchantment should be exiled"
89	    );
90	}
91	#[test]
92	
93	fn brain_weevil_forces_discard() {
94	    let reg = registry();
95	    let mut state = game_at_step(Step::PrecombatMain, P0);
96	
97	    let weevil = named_creature(&mut state, &reg, "Brain Weevil", P0);
98	
99	    // Give P1 exactly 2 cards in hand (auto-discards all when <= 2).
100	    let _c1 = spell_in_hand(&mut state, &reg, "Grizzly Bears", P1);
101	    let _c2 = spell_in_hand(&mut state, &reg, "Lightning Bolt", P1);
102	
103	    let hand_before = state.objects_in_zone(Zone::Hand, P1).len();
104	    assert_eq!(hand_before, 2);
105	
106	    let new_state = mtg_engine::engine::submit_action(
107	        &state,
108	        &Action::ActivateAbility {
109	            object_id: weevil,
110	            ability_index: 0,
111	            targets: vec![Target::Player(P1)],
112	        },
113	        &reg,
114	    );
115	
116	    // Weevil should be in graveyard (sacrificed).
117	    assert_eq!(
118	        new_state.get_object(weevil).unwrap().zone,
119	        Zone::Graveyard,
120	        "Brain Weevil should be sacrificed"
121	    );
122	
123	    // P1 should have discarded 2 cards (2 - 2 = 0 remaining).
124	    let hand_after = new_state.objects_in_zone(Zone::Hand, P1).len();
125	    assert_eq!(hand_after, 0, "P1 should have 0 cards left after discarding 2");
126	}
