137	
138	fn disciple_of_griselbrand_gains_life() {
139	    let reg = registry();
140	    let mut state = game_at_step(Step::PrecombatMain, P0);
141	
142	    let disciple = named_creature(&mut state, &reg, "Disciple of Griselbrand", P0);
143	    // Create a 2/5 creature to sacrifice.
144	    let _fatty = ready_creature(&mut state, P0, 2, 5);
145	
146	    let life_before = state.get_player(P0).life;
147	
148	    // Add mana for the ability: {1}
149	    state.get_player_mut(P0).mana_pool.add(ManaType::Colorless, 1);
150	
151	    let new_state = mtg_engine::engine::submit_action(
152	        &state,
153	        &Action::ActivateAbility {
154	            object_id: disciple,
155	            ability_index: 0,
156	            targets: vec![],
157	        },
158	        &reg,
159	    );
160	
161	    // The engine auto-sacrifices the first creature it finds. It may pick the disciple
162	    // itself (1 toughness) or the fatty (5 toughness). Either way, we gained life.
163	    let life_after = new_state.get_player(P0).life;
164	    let gained = life_after - life_before;
165	    assert!(gained > 0, "Should have gained life, gained {}", gained);
166	}
