169	fn altars_reap_sacrifices_and_draws_two() {
170	    let reg = registry();
171	    let mut state = game_at_step(Step::PrecombatMain, P0);
172	
173	    // Give P0 a creature to sacrifice and cards to draw.
174	    let creature = ready_creature(&mut state, P0, 2, 2);
175	    for _ in 0..3 {
176	        let c = state.create_object(mtg_engine::ids::CardId(9999), P0, Zone::Library, None, None);
177	        state.get_player_mut(P0).library_order.push(c);
178	    }
179	
180	    let spell = castable_spell(&mut state, &reg, "Altar's Reap", P0);
181	    let state = cast_and_resolve(&state, &reg, spell, vec![]);
182	
183	    // Creature should be in graveyard (sacrificed).
184	    assert_eq!(state.get_object(creature).unwrap().zone, Zone::Graveyard,
185	        "Sacrificed creature should be in graveyard");
186	
187	    // Should have drawn 2 cards (hand was empty before spell was added).
188	    let hand_after = state.objects.values()
189	        .filter(|o| o.zone == Zone::Hand && o.owner == P0)
190	        .count();
191	    assert_eq!(hand_after, 2,
